compile.workshop:
variables {
    global:
        0: g
        1: h
}

//Optimizations disabled
rule ("unoptimized") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, -5);
        Set Global Variable(g, Multiply(-1, Global.h));
        Set Global Variable(g, Multiply(-1, Multiply(-1, Global.h)));
        Set Global Variable(g, Add(2, 3));
        Set Global Variable(g, Multiply(Global.h, 0));
    }
}

